public class Main {
    private StringBuilder buffer = new StringBuilder();

    public void feedChunk(String chunk) {
        buffer.append(chunk);
        // TODO: While buffer contains '\n', extract substring before '\n',
        // print "MSG: " + msg, and delete up to and including '\n'.
        int newlineIdx;
        while ((newlineIdx = buffer.indexOf("\n")) != -1) {
            String msg = buffer.substring(0, newlineIdx);
            System.out.println("MSG: " + msg);
            buffer.delete(0, newlineIdx + 1);
        }
    }

    public static void main(String[] args) {
        Main framer = new Main();
        String[] tcpChunks = {
            "JOIN ali",
            "ce\nSEND b",
            "ob Hello!\nLIST\n"
        };
        for (String chunk : tcpChunks) {
            framer.feedChunk(chunk);
        }
        System.out.println("REMAINING: " + framer.buffer.length());
    }
}

