const takenNames = new Set(["alice"]);
let username = null;

function handleLine(line) {
  const parts = line.split(" ");
  const cmd = parts[0];

  if (cmd === "JOIN") {
    if (parts.length !== 2 || !parts[1]) return "ERROR 3 Invalid syntax";
    if (takenNames.has(parts[1])) return "ERROR 1 Username already taken";
    username = parts[1];
    takenNames.add(username);
    return "OK";
  }
  if (cmd === "SEND") {
    if (!username) return "ERROR 2 Must JOIN first";
    const firstSpace = line.indexOf(" ");
    const secondSpace = line.indexOf(" ", firstSpace + 1);
    if (secondSpace === -1) return "ERROR 3 Invalid syntax";
    const recipient = line.slice(firstSpace + 1, secondSpace);
    const msg = line.slice(secondSpace + 1);
    if (msg.length === 0 || msg.length > 100) return "ERROR 3 Invalid message length";
    return `OK (to ${recipient}: ${msg})`;
  }
  return "ERROR 4 Unknown command";
}

const trace = [
  "SEND alice Hi!",
  "JOIN alice",
  "JOIN bob",
  "PING",
  "SEND alice Hello Alice!"
];
for (const line of trace) {
  console.log(`${line} => ${handleLine(line)}`);
}
